type Provider = 'google' | 'facebook' | 'apple';
type Props = { onLogin: (provider: Provider) => void };

export function LoginButtons({ onLogin }: Props) {
  const flags = useRemoteFlags();
  const showApple = Platform.OS === 'ios' && flags.appleLogin === true;

  return (
    <View style={styles.stack}>
      <SocialButton provider="google" onPress={() => onLogin('google')} />
      <SocialButton provider="facebook" onPress={() => onLogin('facebook')} />
      {showApple && <SocialButton provider="apple" onPress={() => onLogin('apple')} />}
    </View>
  );
}

import apn from '@parse/node-apn';

type PushTarget = { deviceToken: string; title: string; body: string };

const provider = new apn.Provider({
  token: {
    key: process.env.APNS_KEY_PATH!,
    keyId: process.env.APNS_KEY_ID!,
    teamId: process.env.APPLE_TEAM_ID!,
  },
  production: process.env.APP_ENV === 'production',
});

export async function sendPush({ deviceToken, title, body }: PushTarget): Promise<void> {
  const note = new apn.Notification();
  note.topic = 'com.acme.parcel';
  note.alert = { title, body };
  const result = await provider.send(note, deviceToken);
  if (result.failed.length > 0) console.error(result.failed[0].response);
}
